<?php
declare(strict_types=1);namespace App\Command;use App\Imperium\Runtime\Senate\ExaminationManifestationStandAdmissionService;use Symfony\Component\Console\Attribute\AsCommand;use Symfony\Component\Console\Command\Command;use Symfony\Component\Console\Input\InputArgument;use Symfony\Component\Console\Input\InputInterface;use Symfony\Component\Console\Input\InputOption;use Symfony\Component\Console\Output\OutputInterface;
#[AsCommand(name:'imperium:senate:admit-examination-manifestation',description:'Validate, admit, and secure one examination Manifestation on the stand')]
final class SenateAdmitExaminationManifestationCommand extends Command{public function __construct(private readonly ExaminationManifestationStandAdmissionService $service){parent::__construct();}protected function configure():void{$this->addArgument('delivery-id',InputArgument::REQUIRED)->addArgument('bailiff-binding-id',InputArgument::REQUIRED)->addOption('json',null,InputOption::VALUE_NONE);}protected function execute(InputInterface $i,OutputInterface $o):int{try{$r=$this->service->admit((string)$i->getArgument('delivery-id'),(string)$i->getArgument('bailiff-binding-id'));}catch(\Throwable $e){$o->writeln('<error>REFUSED</error> '.$e->getMessage());return self::FAILURE;}if((bool)$i->getOption('json')){$o->writeln(json_encode($r,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR));return self::SUCCESS;}$o->writeln('<info>EXAMINATION_MANIFESTATION_ADMITTED</info> '.$r['admission_id']);$o->writeln('Status: '.$r['status']);return self::SUCCESS;}}
